#include "tf_framework.h"

// ---------------------------------------------------------------------------
// tm_units_roundtrip.cpp
//
// NO MOTOR. Pure on-device unit-conversion validation, deeper than
// tm_unit_conversions. For every unit family and EVERY enumerator defined in
// AutoGeneratedUnitConversions.h:
//
//   (1) Round-trip: convert(value, unit, TO_INTERNAL) then FROM_INTERNAL and
//       assert the original value is recovered within 0.01% (relative), across
//       three magnitudes (0.001, 1.0, 1000.0). Temperature uses plausible
//       physical temperatures per unit instead of those raw magnitudes.
//
//   (2) Cross-unit identities checked in internal units:
//         360 deg == 1 rot == 2*pi rad == 3276800 counts
//         1 rot/s == 60 rpm == 360 deg/s
//         1 A == 1000 mA ; 1 V == 1000 mV
//         Celsius / Fahrenheit / Kelvin triangle (0C=32F=273.15K, 100C=212F=373.15K)
//
// The conversion routines are compiled into the library (convertTime,
// convertPosition, ...); this module exercises them directly with no serial
// I/O to the motor. No file-scope mutable state, so nothing to re-init.
// ---------------------------------------------------------------------------

static const float REL_TOL = 1.0e-4f;    // 0.01% relative recovery requirement

// Round-trip magnitudes for the numeric (non-temperature) families.
static const float ROUNDTRIP_MAGS[3] = {0.001f, 1.0f, 1000.0f};

// Generic round-trip check for any family: multiply into internal units then
// divide back out, asserting recovery within REL_TOL (relative). For value v
// the absolute tolerance is |v|*REL_TOL with a tiny floor so v==0 style cases
// (unused here) never demand exact float equality.
template <typename UnitT>
static void roundTripFamily(const char* fam, const char* unitName, UnitT unit,
                            float (*conv)(float, UnitT, ConversionDirection)) {
    for (int i = 0; i < 3; i++) {
        float v = ROUNDTRIP_MAGS[i];
        float internal  = conv(v, unit, ConversionDirection::TO_INTERNAL);
        float recovered = conv(internal, unit, ConversionDirection::FROM_INTERNAL);
        float tol = std::fabs(v) * REL_TOL;
        if (tol < 1.0e-9f) tol = 1.0e-9f;
        char name[128];
        snprintf(name, sizeof(name), "RT %s/%s v=%g", fam, unitName, (double)v);
        bool ok = approxEqual(recovered, v, tol);
        if (!ok)
            printf("  MISMATCH %s/%s: v=%g internal=%g recovered=%g\n",
                   fam, unitName, (double)v, (double)internal, (double)recovered);
        TEST_RESULT(name, ok);
    }
}

// Temperature round-trip with plausible physical temperatures per unit. The
// C<->F conversion carries an offset, so a small absolute tolerance floor is
// used alongside the relative requirement.
static void roundTripTemperature(const char* unitName, TemperatureUnit unit,
                                 const float* temps) {
    for (int i = 0; i < 3; i++) {
        float v = temps[i];
        float internal  = convertTemperature(v, unit, ConversionDirection::TO_INTERNAL);
        float recovered = convertTemperature(internal, unit, ConversionDirection::FROM_INTERNAL);
        float tol = std::fabs(v) * REL_TOL;
        if (tol < 0.01f) tol = 0.01f;
        char name[128];
        snprintf(name, sizeof(name), "RT Temperature/%s v=%g", unitName, (double)v);
        bool ok = approxEqual(recovered, v, tol);
        if (!ok)
            printf("  MISMATCH Temperature/%s: v=%g internal=%g recovered=%g\n",
                   unitName, (double)v, (double)internal, (double)recovered);
        TEST_RESULT(name, ok);
    }
}

void tm_units_roundtrip(void) {
    Serial.println("tm_units_roundtrip: BEGIN (no motor)\n");

    // =======================================================================
    // (1) ROUND-TRIP over EVERY enumerator in every family
    // =======================================================================
    printf("--- Round-trip recovery (0.001, 1.0, 1000.0) ---\n");

    // Time: 5 enumerators
    roundTripFamily("Time", "SECONDS",      TimeUnit::SECONDS,      convertTime);
    roundTripFamily("Time", "MILLISECONDS", TimeUnit::MILLISECONDS, convertTime);
    roundTripFamily("Time", "MINUTES",      TimeUnit::MINUTES,      convertTime);
    roundTripFamily("Time", "MICROSECONDS", TimeUnit::MICROSECONDS, convertTime);
    roundTripFamily("Time", "TIMESTEPS",    TimeUnit::TIMESTEPS,    convertTime);

    // Position: 4 enumerators
    roundTripFamily("Position", "SHAFT_ROTATIONS", PositionUnit::SHAFT_ROTATIONS, convertPosition);
    roundTripFamily("Position", "DEGREES",         PositionUnit::DEGREES,         convertPosition);
    roundTripFamily("Position", "RADIANS",         PositionUnit::RADIANS,         convertPosition);
    roundTripFamily("Position", "ENCODER_COUNTS",  PositionUnit::ENCODER_COUNTS,  convertPosition);

    // Velocity: 6 enumerators
    roundTripFamily("Velocity", "ROTATIONS_PER_SECOND", VelocityUnit::ROTATIONS_PER_SECOND, convertVelocity);
    roundTripFamily("Velocity", "RPM",                  VelocityUnit::RPM,                  convertVelocity);
    roundTripFamily("Velocity", "DEGREES_PER_SECOND",   VelocityUnit::DEGREES_PER_SECOND,   convertVelocity);
    roundTripFamily("Velocity", "RADIANS_PER_SECOND",   VelocityUnit::RADIANS_PER_SECOND,   convertVelocity);
    roundTripFamily("Velocity", "COUNTS_PER_SECOND",    VelocityUnit::COUNTS_PER_SECOND,    convertVelocity);
    roundTripFamily("Velocity", "COUNTS_PER_TIMESTEP",  VelocityUnit::COUNTS_PER_TIMESTEP,  convertVelocity);

    // Acceleration: 6 enumerators
    roundTripFamily("Acceleration", "ROTATIONS_PER_SECOND_SQUARED", AccelerationUnit::ROTATIONS_PER_SECOND_SQUARED, convertAcceleration);
    roundTripFamily("Acceleration", "RPM_PER_SECOND",               AccelerationUnit::RPM_PER_SECOND,               convertAcceleration);
    roundTripFamily("Acceleration", "DEGREES_PER_SECOND_SQUARED",   AccelerationUnit::DEGREES_PER_SECOND_SQUARED,   convertAcceleration);
    roundTripFamily("Acceleration", "RADIANS_PER_SECOND_SQUARED",   AccelerationUnit::RADIANS_PER_SECOND_SQUARED,   convertAcceleration);
    roundTripFamily("Acceleration", "COUNTS_PER_SECOND_SQUARED",    AccelerationUnit::COUNTS_PER_SECOND_SQUARED,    convertAcceleration);
    roundTripFamily("Acceleration", "COUNTS_PER_TIMESTEP_SQUARED",  AccelerationUnit::COUNTS_PER_TIMESTEP_SQUARED,  convertAcceleration);

    // Current: 3 enumerators
    roundTripFamily("Current", "INTERNAL_CURRENT_UNITS", CurrentUnit::INTERNAL_CURRENT_UNITS, convertCurrent);
    roundTripFamily("Current", "MILLIAMPS",              CurrentUnit::MILLIAMPS,              convertCurrent);
    roundTripFamily("Current", "AMPS",                   CurrentUnit::AMPS,                   convertCurrent);

    // Voltage: 2 enumerators
    roundTripFamily("Voltage", "MILLIVOLTS", VoltageUnit::MILLIVOLTS, convertVoltage);
    roundTripFamily("Voltage", "VOLTS",      VoltageUnit::VOLTS,      convertVoltage);

    // Temperature: 3 enumerators, plausible physical temps per unit
    static const float tempsC[3] = {-20.0f,  25.0f, 150.0f};
    static const float tempsF[3] = { -4.0f,  77.0f, 302.0f};
    static const float tempsK[3] = {253.15f, 298.15f, 423.15f};
    roundTripTemperature("CELSIUS",    TemperatureUnit::CELSIUS,    tempsC);
    roundTripTemperature("FAHRENHEIT", TemperatureUnit::FAHRENHEIT, tempsF);
    roundTripTemperature("KELVIN",     TemperatureUnit::KELVIN,     tempsK);

    // =======================================================================
    // (2) CROSS-UNIT IDENTITIES (compared in internal units)
    // =======================================================================
    printf("\n--- Cross-unit identities ---\n");

    // Position: 360 deg == 1 rot == 2*pi rad == 3276800 counts
    {
        float expected = (float)COUNTS_PER_REVOLUTION;   // 3276800
        float tol = expected * REL_TOL;                  // ~328 counts
        float iRot    = convertPosition(1.0f,                    PositionUnit::SHAFT_ROTATIONS, ConversionDirection::TO_INTERNAL);
        float iDeg    = convertPosition(360.0f,                  PositionUnit::DEGREES,         ConversionDirection::TO_INTERNAL);
        float iRad    = convertPosition((float)(2.0 * M_PI),     PositionUnit::RADIANS,         ConversionDirection::TO_INTERNAL);
        float iCounts = convertPosition((float)COUNTS_PER_REVOLUTION, PositionUnit::ENCODER_COUNTS, ConversionDirection::TO_INTERNAL);
        TEST_RESULT("Identity: 1 rot == 3276800 counts",     approxEqual(iRot,    expected, tol));
        TEST_RESULT("Identity: 360 deg == 3276800 counts",   approxEqual(iDeg,    expected, tol));
        TEST_RESULT("Identity: 2*pi rad == 3276800 counts",  approxEqual(iRad,    expected, tol));
        TEST_RESULT("Identity: 3276800 counts (identity)",   approxEqual(iCounts, expected, tol));
    }

    // Velocity: 1 rot/s == 60 rpm == 360 deg/s
    {
        float iRps    = convertVelocity(1.0f,   VelocityUnit::ROTATIONS_PER_SECOND, ConversionDirection::TO_INTERNAL);
        float iRpm    = convertVelocity(60.0f,  VelocityUnit::RPM,                  ConversionDirection::TO_INTERNAL);
        float iDegps  = convertVelocity(360.0f, VelocityUnit::DEGREES_PER_SECOND,   ConversionDirection::TO_INTERNAL);
        float tol = iRps * REL_TOL;
        TEST_RESULT("Identity: 60 rpm == 1 rot/s",    approxEqual(iRpm,   iRps, tol));
        TEST_RESULT("Identity: 360 deg/s == 1 rot/s", approxEqual(iDegps, iRps, tol));
    }

    // Current: 1 A == 1000 mA
    {
        float iAmp = convertCurrent(1.0f,    CurrentUnit::AMPS,      ConversionDirection::TO_INTERNAL);
        float iMa  = convertCurrent(1000.0f, CurrentUnit::MILLIAMPS, ConversionDirection::TO_INTERNAL);
        TEST_RESULT("Identity: 1 A == 1000 mA", approxEqual(iMa, iAmp, iAmp * REL_TOL));
    }

    // Voltage: 1 V == 1000 mV
    {
        float iV  = convertVoltage(1.0f,    VoltageUnit::VOLTS,      ConversionDirection::TO_INTERNAL);
        float iMv = convertVoltage(1000.0f, VoltageUnit::MILLIVOLTS, ConversionDirection::TO_INTERNAL);
        TEST_RESULT("Identity: 1 V == 1000 mV", approxEqual(iMv, iV, iV * REL_TOL));
    }

    // Temperature triangle: internal unit is Celsius.
    {
        float tol = 0.05f;
        // 0 C == 32 F == 273.15 K  -> internal 0
        float c0 = convertTemperature(0.0f,    TemperatureUnit::CELSIUS,    ConversionDirection::TO_INTERNAL);
        float f0 = convertTemperature(32.0f,   TemperatureUnit::FAHRENHEIT, ConversionDirection::TO_INTERNAL);
        float k0 = convertTemperature(273.15f, TemperatureUnit::KELVIN,     ConversionDirection::TO_INTERNAL);
        TEST_RESULT("Identity: 32 F == 0 C",     approxEqual(f0, c0, tol));
        TEST_RESULT("Identity: 273.15 K == 0 C", approxEqual(k0, c0, tol));
        // 100 C == 212 F == 373.15 K -> internal 100
        float c100 = convertTemperature(100.0f,  TemperatureUnit::CELSIUS,    ConversionDirection::TO_INTERNAL);
        float f100 = convertTemperature(212.0f,  TemperatureUnit::FAHRENHEIT, ConversionDirection::TO_INTERNAL);
        float k100 = convertTemperature(373.15f, TemperatureUnit::KELVIN,     ConversionDirection::TO_INTERNAL);
        TEST_RESULT("Identity: 212 F == 100 C",     approxEqual(f100, c100, tol));
        TEST_RESULT("Identity: 373.15 K == 100 C",  approxEqual(k100, c100, tol));
    }

    printf("\ntm_units_roundtrip: END\n");
}
